<template>
<section>
    <loader :is-visible="isLoading"></loader>
    <tg-list :IsShowAction="true" ModuleName="" SubModuleCode="" :LegendArray="[]"
        :RenderRowActionMethod="renderActions" v-on:ActionButtonClick="actionButtonClick" :widgets="[]"
        IdentityColumn="" :listType="['List']" :ListData="BillerData" :HeaderData="Headers"
        :HeaderButtons="listheaderbuttons" :TotalRecords="TotalRecords" :SearchFields="leftSearchFields"
        IsSearchFieldsOnTop="true" :ListDataCallBackFunction="GetBillerListing" :showCheckBox="false"
        :SortExp="SortExp" :SortBy="SortBy" :NorecordfoundText="$t('NoRecordfound')" :HeaderText="$t('ManageBiller')"
        v-on:LeftsearchButtonClick="leftCommonSearch" v-on:PagerButtonClick="pagerMethod"
        v-on:HeaderButtonClick="commonHeaderButtonClick" v-on:SortdataButtonClick="sortdata" :routeInfo="$router" :CurrentPageNumber="CurrentPage">
        <template v-slot:slotdata="{ data }"> 
                <template v-if="['GroupName','GroupInfo'].includes(data.column.COLUMN_NAME) && data.column.DISPLAY_ORDER==2">
                    <span class="text tourguide_a" >
                        <a v-if="data.column.COLUMN_NAME=='GroupName'" @click="GetContractBillerList(data.row)" :title="data.row.GroupName" >
                            <em class="fa fa-eye text-info"></em> {{ truncateText(data.row.GroupName,120) }}
                        </a>
                        <a v-if="data.column.COLUMN_NAME=='GroupInfo'" @click="GetContractBillerList(data.row)" :title="data.row.GroupInfo">
                            <em class="fa fa-eye text-info"></em> {{data.row.GroupInfo}}
                        </a>
                    </span>
                </template>       
                <template v-if="['GroupName'].includes(data.column.COLUMN_NAME) && data.column.DISPLAY_ORDER==1">
                    <span class="text single-action tourguide_a" >
                        <a v-if="data.column.COLUMN_NAME=='GroupName'" @click="GetContractBillerList(data.row)" :title="data.row.GroupName">
                            <span class="" v-html="data.row.GroupName"></span>
                        </a>                       
                    </span>
                </template>       
                <template v-if="data.column.COLUMN_NAME == 'CreatedAt'">
                    <span class="text-center single-action tourguide_a" v-if="data.row.CreatedAt">
                        {{ $options.filters.formatDate(data.row.CreatedAt) }}
                    </span>
                </template>
        </template>
    </tg-list>
    <AssignBiller v-if="isAddBiller" :GroupBy="GroupBy" :editPayload="editPayload" :isEditJsonData="isEditJsonData" :launchMode="assignLaunchMode"></AssignBiller>
    <BillerDetails v-if="isBillerDetail" :GroupBy="GroupBy" :GroupId="GroupId" :GroupName="GroupName" :statusCode="detailStatusCode"></BillerDetails>
    <AssignmentHistory v-if="isHistory" :entityId="historyEntityId" :moduleType="historyModuleType" :entityName="historyEntityName" @close="CloseHistory"></AssignmentHistory>
</section>
</template>

<script>
import Schema from "../Biller/Schema.js";
import DataService from "../../services/DataService.js";
import AssignBiller from "../Biller/AssignBiller.vue";
import BillerDetails from "./BillerDetails.vue";
import AssignmentHistory from "../Biller/AssignmentHistory.vue";
import { locateBillingService } from "../../services/locateBillingService";

const BILLER_LISTING_GROUPBY_KEY = "billing.manageBiller.groupBy";

function cloneHeaderButtonsForGroup(groupBy) {
    const buttons = Schema.buttons.map(b => ({ ...b }));
    if (groupBy === "Contract") {
        buttons[1].isvisible = false;
        buttons[2].isvisible = true;
    } else {
        buttons[1].isvisible = true;
        buttons[2].isvisible = false;
    }
    return buttons;
}

function readStoredGroupBy() {
    try {
        const v = sessionStorage.getItem(BILLER_LISTING_GROUPBY_KEY);
        if (v === "Contract" || v === "Biller") return v;
    } catch (e) {
        /* ignore */
    }
    return "Biller";
}

export default {
    components: { AssignBiller, BillerDetails, AssignmentHistory },
    data() {
        const groupBy = readStoredGroupBy();
        return {
            isLoading: false,
            Headers: [                
                {
                    "COLUMN_NAME": "GroupInfo",
                    "DATA_TYPE": "text",
                    "SORTABLE": true,
                    "VISIBLE": true,
                    "DISPLAY_NAME": 'Biller Name',
                    "DISPLAY_ORDER": 1,
                    settings: {
                        isInSlot: false
                    }
                },
                {
                    "COLUMN_NAME": "GroupName",
                    "DATA_TYPE": "text",
                    "SORTABLE": true,
                    "VISIBLE": true,
                    "DISPLAY_NAME": 'Contracts', 
                    "DISPLAY_ORDER": 2,
                        settings: {
                            isInSlot: true,
                            truncateLength:150
                        }
                },                
                {
                    "COLUMN_NAME": "CreatedBy",
                    "DATA_TYPE": "Date",
                    "SORTABLE": true,
                    "VISIBLE": true,
                    "DISPLAY_NAME": this.$t('CreatedBy'),
                    "DISPLAY_ORDER": 3,
                    // settings: {
                    //     isInSlot: false
                    // }
                },
                {
                    "COLUMN_NAME": "ModifiedBy",
                    "DATA_TYPE": "Date",
                    "SORTABLE": true,
                    "VISIBLE": true,
                    "DISPLAY_NAME": this.$t('ModifiedBy'),
                    "DISPLAY_ORDER": 4,
                    // settings: {
                    //     isInSlot: false
                    // }
                },
                {
                    "COLUMN_NAME": "CreatedAt",
                    "DATA_TYPE": "Date",
                    "SORTABLE": true,
                    "VISIBLE": true,
                    "DISPLAY_NAME": this.$t('CreatedAt'),
                    "DISPLAY_ORDER": 5,
                    settings: {
                        isInSlot: true
                    }
                }
            ],
            SortBy: '',
            SortExp: '',
            PageSize: 10,
            PageNumber: 1,
            TotalRecords: 0,
            CurrentPage: 1,
            TotalPages: 0,
            noRecords: false,
            searchCondition: '',
            BillerData: [],
            editPayload: null,
            listActions: Schema.listActions,
            leftSearchFields: Schema.leftsearchSchema,
            CompanyId: null,
            UserId: null,
            isAddBiller: false,
            isBillerDetail: false,
            isHistory: false,
            historyEntityId: 0,
            historyModuleType: '',
            historyEntityName: '',
            GroupId: 0,
            GroupName: '',
            /** From listing row `status_code` / `STATUS_CODE` (e.g. ACT, INACT) */
            detailStatusCode: '',
            GroupBy: groupBy,
            clientId:'',
            BillerId:'',
            assignLaunchMode: '',
            listheaderbuttons: cloneHeaderButtonsForGroup(groupBy)
        }
    },
     computed: {
        allFlag: {            
            
            get() {
                if (!this.receivedData.length) return false;
                return this.receivedData.every(c => c.isFlag === true);
            },
            set(value) {
                this.receivedData.forEach(c => {
                    c.isFlag = value;
                });
            }
        },

        allInvoice: {
            get() {
                if (!this.receivedData.length) return false;
                return this.receivedData.every(c => c.isInvoice === true);
            },
            set(value) {
                this.receivedData.forEach(c => {
                    c.isInvoice = value;
                });
            }
        },

        allUnprocess: {
            get() {
                if (!this.receivedData.length) return false;
                return this.receivedData.every(c => c.isUnprocess === true);
            },
            set(value) {
                this.receivedData.forEach(c => {
                    c.isUnprocess = value;
                });
            }
        },

        allBilledUnbilled: {
            get() {
                if (!this.receivedData.length) return false;
                return this.receivedData.every(c => c.isBilledUnbilled === true);
            },
            set(value) {
                this.receivedData.forEach(c => {
                    c.isBilledUnbilled = value;
                });
            }
        },

        allRateSchedule: {
            get() {
                if (!this.receivedData.length) return false;
                return this.receivedData.every(c => c.isRateSchedule === true);
            },
            set(value) {
                this.receivedData.forEach(c => {
                    c.isRateSchedule = value;
                });
            }
        },

        allBillingRule: {
            get() {
                if (!this.receivedData.length) return false;
                return this.receivedData.every(c => c.isBillingRule === true);
            },
            set(value) {
                this.receivedData.forEach(c => {
                    c.isBillingRule = value;
                });
            }
        },

        allReport: {
            get() {
                if (!this.receivedData.length) return false;
                return this.receivedData.every(c => c.isReport === true);
            },
            set(value) {
                this.receivedData.forEach(c => {
                    c.isReport = value;
                });
            }
        }
    }, 
    mounted() {
        this.$nextTick(() => {
            setTimeout(() => {
                const resetBtn = document.querySelector('.fa-repeat');
                if (resetBtn) {
                    resetBtn.click();
                }
            }, 500);
        });
    } , 
    created: async function () {
        var vm = this;
        this.$router.replace({ query: {} });
        vm.CompanyId = this.GetUserInfo.CompanyId;
        vm.UserId = this.GetUserInfo.ID;
        await vm.GetBillerListing();
        await vm.fetchclientlist();
        await Schema.bindleftCommonSearchdropdown(vm, "BILLER", "BILLER");
        //await Schema.bindleftCommonSearchdropdown(vm, "BILLER", "CONTRACT");
        
    },
    methods: {
        formatDate(date) {
            if (!date) return '--';
            return new Date(date).toLocaleString();
        },
         fetchclientlist: async function () {
            var vm = this;
            vm.isLoading = true;
            //var url = `reqFrom=CUSTOM`;
            var url = `reqFrom=MANAGEBILLER`;
            try {
                const response = await locateBillingService.getClientList(url);
                vm.clientList = response.data.items || [];
                // Populate the client dropdown in leftSearchFields
                vm.leftSearchFields.find(f => f.fieldName === 'CONTRACT').listOptions = vm.clientList;
            } catch (error) {
                vm.clientList = [];
                vm.leftSearchFields.find(f => f.fieldName === 'CONTRACT').listOptions = [];
                console.error('Error fetching client list:', error);
            } finally {
                vm.isLoading = false;
            }
        },
        AddBiller(){
            var vm = this;
            vm.editPayload= null;            
            vm.isEditJsonData = false;
            vm.assignLaunchMode = '';
            vm.isAddBiller = true;               
        },
        actionButtonClick: function (callbackfunction, item) {
            var vm = this;
            switch (callbackfunction) {
                case "Edit":
                    var privilegeParams = `controller=Biller&action=EditAssignBillerById`;
                    DataService.CheckPrivilege(privilegeParams).then(function (response) {
                        if (response.data) {
                            vm.EditBiller(item);
                        } else {
                            vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                        }
                    });                    
                    break;
                case "Delete":
                    var privilegeParams = `controller=Biller&action=DeleteAssignBiller`;
                    DataService.CheckPrivilege(privilegeParams).then(function (response) {
                        if (response.data) {
                            vm.DeleteBiller(item);
                        } else {
                            vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                        }
                    });
                    break;
                case "Copy":
                    var copyPrivilegeParams = `controller=Biller&action=EditAssignBillerById`;
                    DataService.CheckPrivilege(copyPrivilegeParams).then(function (response) {
                        if (response.data) {
                            vm.CopyBiller(item);
                        } else {
                            vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                        }
                    });
                    break;
                case "History":
                    vm.OpenHistory(item);
                    break;
            }
        },
        OpenHistory(item) {
            var vm = this;
            if (!item || !item.GroupId) {
                vm.ShowAlert(vm.$t('NoRecordfound'), 'warning', true);
                return;
            }
            vm.historyEntityId = Number(item.GroupId) || 0;
            vm.historyModuleType = vm.GroupBy || 'Biller';
            vm.historyEntityName = vm.GroupBy === 'Biller'
                ? (item.GroupInfo || '')
                : (item.GroupName ? String(item.GroupName).replace(/<[^>]+>/g, ' ').trim() : '');
            vm.isHistory = true;
        },
        CloseHistory() {
            this.isHistory = false;
            this.historyEntityId = 0;
            this.historyModuleType = '';
            this.historyEntityName = '';
        },
        EditBiller(item) {
            var vm = this;    
            vm.editPayload = {
                formfields: '',
                AssignBiller: [item]
            };
            vm.assignLaunchMode = '';
            vm.isEditJsonData = true;
            vm.isAddBiller = true;       
        },
        CopyBiller(item) {
            var vm = this;
            vm.editPayload = {
                formfields: '',
                AssignBiller: [item]
            };
            vm.assignLaunchMode = 'copy';
            vm.isEditJsonData = true;
            vm.isAddBiller = true;
        },
        leftCommonSearch: function (value) {
            this.PageNumber = value.PageNumber;
            this.isPaged = 1;
            this.BillerId = '';
            this.clientId = '';
            this.searchCondition = '';

            if (value?.searchConditionJson) {
                const params = new URLSearchParams(value.searchConditionJson);
                this.BillerId = params.get('BillerIds') || '';
                this.clientId = params.get('ClientIds') || '';

            } else if (value?.searchCondition) {
                this.searchCondition = value.searchCondition;
            }else{
                this.$nextTick(() => {
                    setTimeout(() => {
                        const firstBtn = document.querySelector('.page-link.first');
                        if (firstBtn) {                            
                            firstBtn.click();
                        }
                        const input = document.querySelector('#CONTRACT input');
                            if (input) {
                                input.value = '';                                
                        }
                        const wrapper = document.querySelector('#CONTRACT');
                        if (wrapper) {
                            // clear input text
                            const input = wrapper.querySelector('input');
                            if (input) {
                                input.value = '';
                                input.dispatchEvent(new Event('input'));
                                input.dispatchEvent(new Event('change'));
                            }
                            // close dropdown menu
                            const menu = wrapper.querySelector('.autocomplete-menu');
                            if (menu) {
                                menu.style.display = 'none';
                            }
                        }
                    }, 100);
                });                
            }
            this.GetBillerListing();
        },
        commonHeaderButtonClick: function (event) {
            var vm = this;
            switch (event.callbackfunction) {
                case "AddBiller":                    
                    let privilegeParams = `controller=Biller&action=Manage`;
                    DataService.CheckPrivilege(privilegeParams).then(function (response) {
                        if (response.data) {
                            vm.AddBiller();
                        } else {
                            vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                        }
                    });                    
                    break;
                case "GroupByContract":
                    vm.GroupByContract();
                    break;
                case "GroupByBiller":
                    vm.GroupByBiller();
                    break;
            }
        },
        GetContractBillerList(item) {
            var vm = this;
            vm.GroupName = vm.GroupBy == 'Biller' ? item.GroupInfo : item.GroupName;
            vm.GroupId = item.GroupId;
            vm.detailStatusCode = item.status_code ?? item.STATUS_CODE ?? item.Status_Code ?? '';
            vm.isBillerDetail = true;
        },
        applyGroupByHeaderVisibility() {
            const vm = this;
            if (vm.GroupBy === "Contract") {
                vm.listheaderbuttons[1].isvisible = false;
                vm.listheaderbuttons[2].isvisible = true;
            } else {
                vm.listheaderbuttons[1].isvisible = true;
                vm.listheaderbuttons[2].isvisible = false;
            }
        },
        persistGroupBy() {
            try {
                sessionStorage.setItem(BILLER_LISTING_GROUPBY_KEY, this.GroupBy);
            } catch (e) {
                /* ignore */
            }
        },
        GroupByContract(){
            var vm=this;
            vm.GroupBy='Contract';
            vm.applyGroupByHeaderVisibility();
            vm.persistGroupBy();
            vm.GetBillerListing();
        },
        GroupByBiller(){
            var vm=this;
            vm.GroupBy='Biller';
            vm.applyGroupByHeaderVisibility();
            vm.persistGroupBy();
            vm.GetBillerListing();           
        },
        sortdata: function (sortBy) {
            this.SortBy = sortBy;
            var sortExp = 'ASC';
            if (this.SortExp == 'ASC') {
                sortExp = 'DESC';
            }
            this.SortExp = sortExp;
            this.SortBy = sortBy;
            this.SortExp = sortExp;
            this.PageNumber = 1;
            this.GetBillerListing();
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.GetBillerListing();
        },
        renderActions: function (row) {
            var self = this;
            let rtnActionArray = [];
            self.listActions.forEach(actionItem => {
                let action = {
                    ...actionItem
                };
                switch (action.title) {
                    case 'Edit':
                        action.isVisible = true;
                    case 'Copy':
                        action.isVisible = true;
                    case 'Delete':
                        action.isVisible = true;
                        break;
                    default: {
                        action.isVisible = true;
                    }
                }
                rtnActionArray.push(action);
            });
            return rtnActionArray;
        },       
        GetBillerListing: async function () {
            var vm = this;
            vm.isLoading = true;
            vm.TotalRecords=0;
            var privilegeParams = `controller=Biller&action=BillerListing`;
              DataService.CheckPrivilege(privilegeParams).then(async function (response) {
                if (!response.data) {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                    return;
                }            
                var params = `groupBy=${vm.GroupBy}&billerIds=${vm.BillerId}&clientIds=${vm.clientId}&sortBy=${vm.SortBy}&sortExp=${vm.SortExp}&pageSize=${vm.PageSize}&pageNum=${vm.PageNumber}&isPartial=${0}`
                // Switch to POST automatically when the query string would be too long for a GET request
                // (browsers/IIS commonly cap URLs around ~2048 chars; use 1800 as a safe threshold).
                var QUERY_STRING_LIMIT = 1800;
                var listingCall;
                if (params.length > QUERY_STRING_LIMIT) {
                    listingCall = DataService.GetBillerListingPost({
                        GroupBy: vm.GroupBy,
                        BillerIds: vm.BillerId == null ? '' : String(vm.BillerId),
                        ClientIds: vm.clientId == null ? '' : String(vm.clientId),
                        SortBy: vm.SortBy,
                        SortExp: vm.SortExp,
                        PageSize: vm.PageSize,
                        PageNum: vm.PageNumber,
                        IsPartial: 0
                    });
                } else {
                    listingCall = DataService.GetBillerListing(params);
                }
                await listingCall.then((response) => {
                    if (response.data.result.length > 0 && response.data.result!='[]') {
                            if (vm.GroupBy === 'Biller') {
                                vm.Headers = vm.Headers.map(h => {
                                    if (h.COLUMN_NAME === 'GroupInfo') {
                                        return {
                                            ...h,
                                            DISPLAY_ORDER: 1,
                                            settings: { isInSlot: false }
                                        };
                                    }
                                    if (h.COLUMN_NAME === 'GroupName') {
                                        return {
                                            ...h,
                                            DISPLAY_ORDER: 2,
                                            settings: { isInSlot: true }
                                        };
                                    }
                                    return h;
                                });

                            } else {
                                vm.Headers = vm.Headers.map(h => {
                                    if (h.COLUMN_NAME === 'GroupName') {
                                        return {
                                            ...h,
                                            DISPLAY_ORDER: 1,
                                            settings: { isInSlot: true }
                                        };
                                    }
                                    if (h.COLUMN_NAME === 'GroupInfo') {
                                        return {
                                            ...h,
                                            DISPLAY_ORDER: 2,
                                            settings: { isInSlot: true }
                                        };
                                    }
                                    return h;
                                });
                            }
                            vm.Headers.sort((a, b) => a.DISPLAY_ORDER - b.DISPLAY_ORDER);

                        vm.BillerData = JSON.parse(response.data.result);
                        vm.TotalRecords = vm.BillerData[0].TOTAL_RECORDS;
                        vm.TotalPages = Math.ceil(vm.TotalRecords / vm.PageSize);
                        vm.CurrentPage = vm.PageNumber;                   
                        vm.noRecords = false;
                        vm.isLoading = false;
                    } else {
                        if(vm.PageNumber !==1){
                            vm.PageNumber=1;
                            vm.GetBillerListing(); 
                        }
                        vm.BillerData = [];
                        vm.noRecords = true;
                        vm.TotalRecords = 0
                        vm.isLoading = false;
                    }
                })
            });
        },
        DeleteBiller(item) {
            var vm = this;
            if (!item || !item.GroupId) {
                vm.ShowAlert(vm.$t("Selectanyrecordtodelete"));
                return;
            }
            // PRIVILEGE-CHECK: Biller / DeleteAssignBiller (added for Delete biller)
            var privilegeParams = `controller=Biller&action=DeleteAssignBiller`;
            DataService.CheckPrivilege(privilegeParams).then(function (response) {
                if (!response.data) {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                    return;
                }
                vm.confirmR(vm.$t("ConfirmDelete"), true, vm.$t("Delete") + " " + vm.$t("Biller"),
                    function () {
                        vm.isLoading = true;
                        var biller=vm.GroupBy ? vm.GroupBy : 'Biller';
                        var url = `groupId=${item.GroupId}&groupBy=${biller}`;

                        DataService.DeleteAssignBiller(url).then(function (response) {
                            if (response.status === 200) {
                                vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Biller')]),"success",true,vm.$t("Alert"));
                                vm.GetBillerListing();
                            } else {
                                vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Biller')]),"error",true,vm.$t("Alert"));
                            }
                            vm.isLoading = false;
                        });
                    }
                );
            });
        }
     
    }
}
</script>