<template>
<div class="my-popups">
    <loader :is-visible="Loading"></loader>
    <div class="modal my-popups right fade d-block" :class="{ show: isShown }">
        <div role="document" class="modal-dialog" style="max-width: 1200px !important;">
            <div class="modal-content">
                <div class="modal-header theme-primary partition-full d-flex">
                    <h4 class="modal-title">Copy Biller(s) to Contract</h4>
                    <button type="button" class="close" @click="Close">
                        <em class="fa fa-times" aria-hidden="true"></em>
                    </button>
                </div>
                <div class="modal-body">
                    <div class="tab-content">
                        <div class="tab-pane active show">
                            <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left p-0">
                                <div class="col-lg-12 float-left p-0">
                                    <dynamic-form lang="en" ref="CopyBillerForm" :schema="FormSchema"></dynamic-form>
                                </div>
                                <div class="col-lg-12 float-left p-0">
                                    <div class="col-12 p-0 d-flex flex-wrap mb-2">
                                        <div class="col-12 p-0">
                                            <div class="row m-0">
                                                <div class="heading-border mb-2">
                                                    <h5 class="h5">
                                                        <span>Selected Billers ({{ filteredBillers.length }})</span>
                                                    </h5>
                                                </div>
                                                <div class="pt-2 d-inline-block w-100">
                                                    <div class="col-12 p-0 mt-0">
                                                        <div class="col-6 col-sm-6 col-md-6 col-lg-6 col-xl-6 float-left pr-1 pl-0">
                                                            <input maxlength="50" class="form-control" type="text" v-model="Searchtext" placeholder="Search by Biller Name" autocomplete="off">
                                                        </div>
                                                        <div class="col-6 col-sm-6 col-md-6 col-lg-6 col-xl-6 float-left pl-0">
                                                            <div class="search-btm-btn background-0 form-check-inline">
                                                                <button title="Search" @click="SearchButton(Searchtext)" class="btn btn-success mr-1 px-4">
                                                                    <em class="fa fa-search"></em> Search
                                                                </button>
                                                                <button title="Clear" class="btn btn-danger px-4" @click="Clear">
                                                                    <em class="fa fa-refresh"></em> Clear
                                                                </button>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                                <div class="col-md-12 p-0">
                                                    <div class="listing mt-2">
                                                        <div class="table-responsive table-fix-header float-left">
                                                            <table class="table table-bordered mt-0" style="width:100%">
                                                                <thead class="thead-bg">
                                                                    <tr>
                                                                        <th style="width:30%">Biller Name</th>
                                                                        <th class="text-center" style="width:10%">{{ $t('Flag') }}</th>
                                                                        <th class="text-center" style="width:10%">{{ $t('Invoice') }}</th>
                                                                        <th class="text-center" style="width:10%">{{ $t('Unprocess') }}</th>
                                                                        <th class="text-center" style="width:12%">{{ $t('BilledUnbilled') }}</th>
                                                                        <th class="text-center" style="width:12%">{{ $t('RateSchedule') }}</th>
                                                                        <th class="text-center" style="width:12%">{{ $t('BillingRule') }}</th>
                                                                        <th class="text-center" style="width:12%">{{ $t('Report') }}</th>
                                                                    </tr>
                                                                </thead>
                                                                <tbody>
                                                                    <tr v-for="biller in filteredBillers" :key="rowKey(biller)">
                                                                        <td><span :title="stripHtml(biller.billerName)" v-html="biller.billerName"></span></td>
                                                                        <td><label class="switch"><input type="checkbox" v-model="biller.isFlag"><span class="slider round"><span class="slider-yes">{{ $t('Yes') }}</span><span class="slider-no">{{ $t('No') }}</span></span></label></td>
                                                                        <td><label class="switch"><input type="checkbox" v-model="biller.isInvoice"><span class="slider round"><span class="slider-yes">{{ $t('Yes') }}</span><span class="slider-no">{{ $t('No') }}</span></span></label></td>
                                                                        <td><label class="switch"><input type="checkbox" v-model="biller.isUnprocess"><span class="slider round"><span class="slider-yes">{{ $t('Yes') }}</span><span class="slider-no">{{ $t('No') }}</span></span></label></td>
                                                                        <td><label class="switch"><input type="checkbox" v-model="biller.isBilledUnbilled"><span class="slider round"><span class="slider-yes">{{ $t('Yes') }}</span><span class="slider-no">{{ $t('No') }}</span></span></label></td>
                                                                        <td><label class="switch"><input type="checkbox" v-model="biller.isRateSchedule"><span class="slider round"><span class="slider-yes">{{ $t('Yes') }}</span><span class="slider-no">{{ $t('No') }}</span></span></label></td>
                                                                        <td><label class="switch"><input type="checkbox" v-model="biller.isBillingRule"><span class="slider round"><span class="slider-yes">{{ $t('Yes') }}</span><span class="slider-no">{{ $t('No') }}</span></span></label></td>
                                                                        <td><label class="switch"><input type="checkbox" v-model="biller.isReport"><span class="slider round"><span class="slider-yes">{{ $t('Yes') }}</span><span class="slider-no">{{ $t('No') }}</span></span></label></td>
                                                                    </tr>
                                                                    <tr v-if="filteredBillers.length === 0">
                                                                        <td colspan="8" class="text-danger text-center">{{ $t('NorecordfoundText') }}</td>
                                                                    </tr>
                                                                </tbody>
                                                            </table>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                            <div class="clearfix"></div>
                                            <div class="row flex-row-reverse mt-2">
                                                <div class="col-lg-6 text-right">
                                                    <div class="search-btm-btn">
                                                        <button @click="CopyBillers" class="btn btn-success" style="float:right;margin-left: 10px">
                                                            <i class="fa fa-copy pr-2"></i><span>Copy Billers</span>
                                                        </button>
                                                        <button @click="Close" style="float:right;" class="btn btn-danger">
                                                            <em class="fa fa-close pr-2"></em>{{ $t('Cancel') }}
                                                        </button>
                                                    </div>
                                                </div>
                                                <div class="col-lg-6">
                                                    <div class="py-2">
                                                        <span class="mandatory">{{ $t('MandatoryString') }}</span>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>
</template>

<script>
import DataService from '../../services/DataService';

export default {
    props: {
        selectedBillers: {
            type: Array,
            required: true,
            default: () => []
        },
        currentContractId: {
            type: [Number, String],
            required: false,
            default: 0
        }
    },
    data() {
        return {
            Loading: false,
            isShown: false,
            Searchtext: '',
            billersMaster: [],
            filteredBillers: [],
            FormSchema: [{
                layoutType: "single",
                Data: [{
                    astype: "SearchableSelectField",
                    label: "Assign these to Contract",
                    name: "Contract",
                    // Empty string is the convention used elsewhere in the
                    // codebase (see AssignBiller.vue) for SearchableSelectField
                    // multi-select fields; the dynamic-form component
                    // promotes it to an array internally when isMultiple=true.
                    value: "",
                    placeholder: "Select Contract(s)",
                    visibility: true,
                    isSearch: true,
                    config: {
                        options: [],
                        // selectAll/clear action buttons mirror the AssignBiller
                        // multi-select biller field for a consistent UX.
                        actionButtons: { selectAll: true, clear: true },
                        isMultiple: true,
                        itemFields: ['text'],
                        minSearchLength: 0
                    },
                    disabled: false,
                    validationRules: { "required": true }
                }]
            }]
        };
    },
    created() {
        this.billersMaster = (this.selectedBillers || []).map(b => ({
            billerId: Number(b.billerId || 0),
            billerName: b.billerName || '',
            isFlag: !!b.isFlag,
            isInvoice: !!b.isInvoice,
            isUnprocess: !!b.isUnprocess,
            isBilledUnbilled: !!b.isBilledUnbilled,
            isRateSchedule: !!b.isRateSchedule,
            isBillingRule: !!b.isBillingRule,
            isReport: !!b.isReport
        }));
        this.filteredBillers = this.billersMaster.slice();
    },
    mounted() {
        this.$nextTick(() => {
            this.isShown = true;
            this.GetContractList();
        });
    },
    methods: {
        stripHtml(s) {
            if (!s) return '';
            return String(s).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
        },
        rowKey(b) {
            return `${b.billerId}`;
        },
        async GetContractList() {
            const vm = this;
            vm.Loading = true;
            try {
                const url = `pageNum=&pageSize=1000000&reqFrom=MANAGEBILLER&search=&userId=&screenName=`;
                const response = await DataService.GetAvailableContracts(url);
                const contracts = response?.data?.result || [];
                const sourceContractId = Number(vm.currentContractId || 0);
                const options = contracts.map(item => ({
                    text: item.CHILD_NAME,
                    value: item.CHILD_USER_ID,
                    displayValue: item.CHILD_NAME
                })).filter(item => Number(item.value) !== sourceContractId);
                const field = vm.FormSchema[0].Data.find(f => f.name === 'Contract');
                if (field) field.config.options = options;
                vm.$refs.CopyBillerForm?.UpdateKeyValue();
            } catch (e) {
                console.error('GetContractList error:', e);
            } finally {
                vm.Loading = false;
            }
        },
        SearchButton(txt) {
            const query = (txt || '').trim().toLowerCase();
            if (!query) {
                this.filteredBillers = this.billersMaster.slice();
                return;
            }
            this.filteredBillers = this.billersMaster.filter(b => this.stripHtml(b.billerName).toLowerCase().includes(query));
        },
        Clear() {
            this.Searchtext = '';
            this.filteredBillers = this.billersMaster.slice();
        },
        async CopyBillers() {
            // The SearchableSelectField in multi-select mode binds an array of
            // ids; in single-select mode (legacy) it binds a scalar. Normalize
            // both shapes to an array of positive numeric ids.
            const rawValue = this.FormSchema?.[0]?.Data?.[0]?.value;
            const targetContractIds = (Array.isArray(rawValue) ? rawValue : (rawValue != null && rawValue !== '' ? [rawValue] : []))
                .map(v => Number(v))
                .filter(v => v > 0);

            if (!targetContractIds.length) {
                this.ShowAlert("Please select at least one contract", "warning", true);
                return;
            }
            if (!this.billersMaster.length) {
                this.ShowAlert("No billers selected to copy", "warning", true);
                return;
            }
            const payload = {
                // Send both the new multi-target field and the legacy single
                // target so the API works regardless of which version of the
                // backend is deployed.
                targetContractIds: targetContractIds,
                targetContractId: targetContractIds[0],
                selectedBillers: this.billersMaster.map(b => ({
                    billerId: Number(b.billerId),
                    isFlag: !!b.isFlag,
                    isInvoice: !!b.isInvoice,
                    isUnprocess: !!b.isUnprocess,
                    isBilledUnbilled: !!b.isBilledUnbilled,
                    isRateSchedule: !!b.isRateSchedule,
                    isBillingRule: !!b.isBillingRule,
                    isReport: !!b.isReport
                }))
            };
            this.Loading = true;
            try {
                const response = await DataService.CopyBillersToContract(payload);
                const isSuccess = response?.data?.status === 'Success' || response?.data?.Status === 'Success' || response?.data?.Code === "1" || response?.data?.code === "1";
                if (!isSuccess) {
                    throw new Error(response?.data?.msg || response?.data?.Msg || "Failed to copy billers");
                }
                this.ShowAlert("Billers copied successfully", "success", true);
                this.$emit('copied');
            } catch (e) {
                this.ShowAlert(e.message || "Failed to copy billers", "danger", true);
            } finally {
                this.Loading = false;
            }
        },
        Close() {
            this.$emit('close');
        }
    }
};
</script>
